<?php
$page_id = 'transaction_details';
require_once __DIR__ . '/../backend/lib.php';
require_once __DIR__ . '/../public/db_connect.php';
require_login();  $me = current_user();
$station_id = user_station_id();
$role = role_key($me['role'] ?? '');  // Restrict access
if (!in_array($role, ['manager', 'admin', 'superadmin', 'staff', 'cashier', 'pump_attendant'])) {  $_SESSION['error'] = 'Access denied';  header('Location: dashboard.php');  exit;
}  $transaction_id = $_GET['id'] ?? 0;  // Check if it's a fuel transaction (starts with FUELREC_)
$transaction = null;
if (strpos($transaction_id, 'FUELREC_') === 0) {  // Get fuel transaction details  $stmt = $pdo->prepare("SELECT  ft.transaction_id,  ft.created_at,  ft.status,  u.name as staff_name,  u.role as staff_role,  'Fuel Transaction' as customer,  ft.payment_method,  ft.fuel_type as product_name,  ft.liters_sold as quantity,  ft.price_per_liter as unit_price,  ft.total_amount,  'Fuel' as category,  'Fuel Transaction' as transaction_type,  ft.pump_id,  ft.present_reading,  ft.previous_reading,  ft.calibration  FROM fuel_transactions ft  LEFT JOIN users u ON ft.staff_id = u.id  WHERE ft.transaction_id = ? AND ft.station_id = ?");  $stmt->execute([$transaction_id, $station_id]);  $transaction = $stmt->fetch(PDO::FETCH_ASSOC);
} else {  // Get regular sales transaction details  $stmt = $pdo->prepare("SELECT  s.id as transaction_id,  s.created_at,  s.status,  s.customer_id,  s.payment_method,  u.name as staff_name,  u.role as staff_role,  COALESCE(c.name, s.customer, 'Walk-in') as customer,  si.name as product_name,  si.quantity,  si.unit_price,  si.total_amount,  si.pump_id,  si.nozzle_id,  CASE  WHEN ip.category = 'Fuel' THEN 'Fuel'  WHEN ip.category IS NOT NULL THEN ip.category  WHEN pt.name IS NOT NULL THEN pt.name  ELSE 'Merchandise'  END as category,  CASE  WHEN ip.category = 'Fuel' THEN 'Fuel Transaction'  WHEN ip.category IS NOT NULL THEN 'Merchandise Transaction'  ELSE 'General Transaction'  END as transaction_type,  ip.unit_cost as current_price,  ip.size as product_size  FROM sales s  JOIN sale_items si ON s.id = si.sale_id  LEFT JOIN users u ON s.user_id = u.id  LEFT JOIN customers c ON s.customer_id = c.id  LEFT JOIN inventory_products ip ON si.name = ip.product_name  LEFT JOIN products p ON si.product_id = p.id  LEFT JOIN product_types pt ON p.type_id = pt.id  WHERE s.id = ? AND s.station_id = ?");  $stmt->execute([$transaction_id, $station_id]);  $transaction = $stmt->fetch(PDO::FETCH_ASSOC);
}  if (!$transaction) {  $_SESSION['error'] = 'Transaction not found';  header('Location: transactions.php');  exit;
}  // Get audit logs for this transaction
$audit_logs = [];
try {  $stmt = $pdo->prepare("SELECT  al.action,  al.details,  al.created_at,  u.name as action_user  FROM audit_log al  LEFT JOIN users u ON al.user_id = u.id  WHERE al.details LIKE ?  ORDER BY al.created_at DESC  LIMIT 10");  $stmt->execute(['%Transaction #$transaction_id%']);  $audit_logs = $stmt->fetchAll(PDO::FETCH_ASSOC);
} catch(Exception $e) {}  include __DIR__ . '/../partials/header.php';
